<script lang="ts">import { onMount } from 'svelte'; import { api } from '$lib/api'; import StudentShell from '$lib/components/StudentShell.svelte'; import { apiError, requireStudent, type StudentSession } from '$lib/student-session'; let session: StudentSession | null = null; let items: any[] = []; let goldStars: any[] = []; let error = ''; onMount(async () => { session = await requireStudent(); if (!session) return; try { [items, goldStars] = await Promise.all([api<any[]>('/api/student/achievements'), api<any[]>('/api/student/gold-stars')]); } catch (e) { error = apiError(e); } });</script>
{#if session}<StudentShell {session} active="achievements"><section class="student-heading"><span class="student-eyebrow">MILESTONES & GOLD STARS</span><h1>ACHIEVEMENTS</h1><p>Every earned badge and special event is a record of consistent training.</p></section>{#if error}<div class="error">{error}</div>{:else}<section class="student-panel gold-star-panel"><div class="panel-title"><span>GOLD-STAR EVENTS</span><span class="muted">Awarded by the dojo</span></div><p class="muted">Special studio events can earn a gold star. Attendance and awards are recorded by staff; students cannot award themselves.</p>{#if goldStars.length}<div class="gold-star-grid">{#each goldStars as event}<a href={`/student/achievements/${event.eventId}`} class:awarded={event.awarded} class="gold-star-card"><span class="gold-star-icon">★</span><div><h2>{event.name}</h2><p>{event.description}</p><small>{event.awarded ? 'Gold star earned · View details →' : 'Event opportunity · View details →'}</small></div></a>{/each}</div>{:else}<p class="muted">No gold-star events are published yet.</p>{/if}</section>{#if items.length}<div class="achievement-grid">{#each items as item}<article class="achievement-card"><span class="achievement-icon">{item.iconName ?? '★'}</span><div><h2>{item.name}</h2><p>{item.description ?? 'Dojo milestone earned.'}</p><small>{item.awardedAt ? new Date(item.awardedAt).toLocaleDateString() : ''}</small></div></article>{/each}</div>{:else}<section class="student-panel empty-panel"><span class="rank-orb">★</span><h2>Your next milestone is ahead.</h2><p>Keep training. Achievements awarded by the dojo will appear here.</p></section>{/if}{/if}</StudentShell>{/if}
